"""Stage isolated original/Host-DAX Runtime configs; never start a service.

Retained deployments, snapshot payloads and the synthetic UB experiment are
read-only inputs. Copies executable bytes only, not template payloads.
"""
import argparse,base64,copy,hashlib,json,os,re,secrets,stat,subprocess,sys,tomllib,zlib
from pathlib import Path
ROOT=Path('/home/jwk/agent')
PROBE=''
PROBE_SHA='6313625749f5addd473de374038a75cf888dfbec0296bb2f612abb38939158bc'
IMAGE_SHA='68e386f9ad745c7c9a19de5dad354e175b62b5a8296a53e559468d562c8addc5'
OBS_SHA='eed36d01de13f83a8abdc13e93c21883a3a48273da83fa1c813e65e4655babcf'
OBS_A=ROOT/'relay/reports/node-a-rootfs-access-build-abcks95d/candidate/uvm-ublk-daemon-observe'
VERSIONS={'original':{'base':'agentenv-ae9c626-baseline',
    'server':'0c5478b8382289c05ab1730401eea6918420c35594604cc7131592e81ad5aeff',
    'sourceDaemon':'13bd2ac381cf877348a39c0b198e2061479ae237c0f54cbcbeae0ab14e700172',
    'daemon':OBS_SHA,'fc':'a64b8f068d47bd6ec85aa755b8f8863e16d0ae14be551376218fed401ee0bdf8'},
    'dax':{'base':'agentenv-direct-ub-deletefix-v1',
    'server':'759423e634e25bc2e74067bfaccc16e40720907fc0e717269261dd573f0097df',
    'sourceDaemon':'5291c267777cd91c4b853c6d40720e8d87200b2a0162024782534c4126cba726',
    'daemon':'5291c267777cd91c4b853c6d40720e8d87200b2a0162024782534c4126cba726',
    'fc':'e9588526096f45380b8debf2d41bf33a2fb26f8abea0a9bed841627327782a0b'}}

def need(value,reason):
    if not value:raise RuntimeError(reason)

def read(path,limit=1024**2):
    need(path.resolve(strict=True)==path,'Redirected source file: '+str(path))
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(fd,'rb') as f:
        info=os.fstat(f.fileno())
        need(stat.S_ISREG(info.st_mode) and info.st_uid in (0,1204) and 0<info.st_size<=limit,'Unexpected source file')
        return f.read(limit+1)

def sha(path):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(fd,'rb') as f:
        before=os.fstat(f.fileno());need(stat.S_ISREG(before.st_mode) and before.st_uid in (0,1204),'Invalid binary')
        h=hashlib.sha256()
        for data in iter(lambda:f.read(1024**2),b''):h.update(data)
        after=os.fstat(f.fileno())
    need((before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns)==
         (after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns),'Source changed')
    return h.hexdigest()

def mkdir(path):
    if not path.exists():path.mkdir(mode=0o700)
    info=path.lstat()
    need(path.resolve(strict=True)==path and stat.S_ISDIR(info.st_mode) and info.st_uid==1204
         and not info.st_mode&0o022,'Unsafe staging directory')

def put(path,data,mode=0o600):
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
    with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fchmod(f.fileno(),mode);os.fsync(f.fileno())

def copy_binary(source,target,pin):
    source=source.resolve(strict=True)
    need(source.is_relative_to(ROOT) and sha(source)==pin,'Retained binary bytes differ: '+str(source))
    with source.open('rb') as a:
        fd=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o700)
        with os.fdopen(fd,'wb') as b:
            for data in iter(lambda:a.read(1024**2),b''):b.write(data)
            b.flush();os.fsync(b.fileno())
    need(sha(target)==pin and sha(source)==pin,'Copied binary changed')

def toml_bytes(config):
    lines=[]
    def table(value,prefix):
        scalars={k:v for k,v in value.items() if not isinstance(v,dict)}
        if prefix:lines.append('['+'.'.join(prefix)+']')
        for k,v in scalars.items():
            need(re.fullmatch('[A-Za-z0-9_-]+',k) is not None and v is not None,'Unsupported config scalar')
            lines.append(k+' = '+json.dumps(v,ensure_ascii=False,separators=(',',':')))
        lines.append('')
        for k,v in value.items():
            if isinstance(v,dict):
                need(re.fullmatch('[A-Za-z0-9_-]+',k) is not None,'Unsupported config section')
                table(v,prefix+[k])
    table(config,[]);raw=('\n'.join(lines)+'\n').encode()
    need(tomllib.loads(raw.decode())==config,'Staged TOML does not preserve config')
    return raw

def configure(source,variant,node,work,base,snapshot_store):
    config=copy.deepcopy(source)
    config['home_path']=str(base/'state');config['runtime_path']=str(work/('run-'+variant))
    # Public assets and native shared libraries remain retained, immutable inputs.
    config['deps_path']=str(ROOT/'deployments'/VERSIONS[variant]['base']/'deps')
    fc=config.setdefault('firecracker',{})
    fc.update(binary_path=str(base/'bin/firecracker'),work_dir=str(work/(variant+'-fc')),
              serial_dir=str(base/'logs/firecracker'),log_level='Info')
    path=str(Path(fc['work_dir'])/'agentenv-fc-XXXXXX/firecracker.socket')
    need(len(path.encode())<=107,'FC socket path exceeds Linux pathname limit')
    config.setdefault('backend',{}).setdefault('posix_fs',{})['snapshot_store']=str(snapshot_store)
    config.setdefault('snapshot',{}).update(repository_backend='posix_fs',p2p_enabled=False)
    for key in ('ub_rootfs_index','ub_rootfs_index_sha256','ub_rootfs_demand_manifest'):
        config['snapshot'].pop(key,None)
    config.setdefault('ublk',{}).update(daemon_binary_path=str(base/'bin/uvm-ublk-daemon'),
        daemon_log_path=str(base/'logs/ublk-daemon.log'),daemon_metrics_listen_addr='')
    config.setdefault('image',{}).setdefault('cache',{}).setdefault('gc',{})['enabled']=False
    config.setdefault('p2p',{})['enabled']=False
    for key in ('network','block','firecracker'):
        group=config.setdefault('pool',{}).setdefault(key,{})
        if key=='network':group['maintenance_enabled']=False
        else:group.update(startup_prewarm=False,enabled=key=='block')
    config.setdefault('node_identity',{})['service_instance_id']='hpd4-'+node+'-'+variant
    return config

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--stage',action='store_true')
    args=parser.parse_args();node={'server1':'a','agent1':'b'}[os.uname().nodename]
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==1205,'Run as ordinary jwk')
    work=ROOT/'r'/('hpd4-'+node+'-v1')
    prepared=json.loads(read(work/'prepared.json'))
    need(prepared['status']=='HOST_DAX_REAL_TEMPLATE_PREPARED_NO_SDK' and prepared['node']==node,'Preparation receipt differs')
    if node=='a':need(prepared['image']['sha256']==IMAGE_SHA,'Prepared A image differs')
    observer=OBS_A if node=='a' else work/'uvm-ublk-daemon-original-observer'
    report={'node':node,'status':'HOST_DAX_RUNTIME_STAGE_PLAN','imageSha256':IMAGE_SHA,
            'servicesChanged':False,'SDK_called':False,'Guest_created':False,'moduleChanged':False}
    if not observer.exists():
        report.update(status='HOST_DAX_RUNTIME_STAGE_NEEDS_RETAINED_OBSERVER',
            requiredFile=str(observer),expectedSha256=OBS_SHA,sourceOnA=str(OBS_A))
        print(json.dumps(report,indent=2));return
    need(sha(observer)==OBS_SHA,'Retained original diagnostic observer differs')
    profile={}
    for variant,row in VERSIONS.items():
        source=ROOT/'deployments'/row['base']
        need(sha(source/'bin/server')==row['server'] and sha(source/'bin/uvm-ublk-daemon')==row['sourceDaemon'],
             'Retained Runtime/daemon changed')
        raw=read(source/'config/runtime.toml');config=tomllib.loads(raw.decode())
        fc=Path(config['firecracker']['binary_path']).resolve(strict=True)
        need(fc.is_relative_to(ROOT) and sha(fc)==row['fc'],'Retained Firecracker differs')
        profile[variant]={'source':source,'config':config,'fc':fc,'configSha256':hashlib.sha256(raw).hexdigest()}
    stage=work/'runtime-stage'
    need(not stage.exists() and not stage.is_symlink(),'Existing Runtime stage preserved; do not repeat')
    if not args.stage:
        print(json.dumps(report,indent=2));return
    stage.mkdir(mode=0o700)
    probe=zlib.decompress(base64.b64decode(PROBE,validate=True))
    need(hashlib.sha256(probe).hexdigest()==PROBE_SHA,'Static Guest probe differs')
    put(stage/'guest-read-probe-aarch64',probe,0o700)
    fixture=stage/'probe-self-test.data';put(fixture,bytes(range(256))*16)
    test=subprocess.run([str(stage/'guest-read-probe-aarch64'),'--max-bytes','8192','--block-bytes','4096','--',str(fixture)],
                        stdin=subprocess.DEVNULL,capture_output=True,timeout=20)
    put(stage/'probe-self-test.json',test.stdout)
    need(test.returncode==0,'Static read probe failed on native Host: '+test.stderr.decode(errors='replace')[-1000:])
    observed=json.loads(test.stdout)
    need(observed['state']=='completed' and observed['actualBytes']==8192 and len(observed['reads'])==2
         and all(row['error']==0 and row['bytes']==4096 and row['endNs']>=row['startNs'] for row in observed['reads']),
         'Native read probe did not perform the expected readonly calls')
    variants={};snapshot_store=ROOT/'deployments/agentenv-lazy-four-32ce41c/state/snapshot-store'
    for variant,profile_row in profile.items():
        row=VERSIONS[variant];base=stage/variant;mkdir(base)
        for name in ('bin','state','config','logs','logs/firecracker','tmp','cache'):
            mkdir(base/name)
        mkdir(work/('run-'+variant));mkdir(work/(variant+'-fc'))
        copy_binary(profile_row['source']/'bin/server',base/'bin/server',row['server'])
        copy_binary(observer if variant=='original' else profile_row['source']/'bin/uvm-ublk-daemon',base/'bin/uvm-ublk-daemon',row['daemon'])
        copy_binary(profile_row['fc'],base/'bin/firecracker',row['fc'])
        config=configure(profile_row['config'],variant,node,work,base,snapshot_store)
        raw=toml_bytes(config);put(base/'config/runtime.toml',raw)
        put(base/'config/api-key',('e2b_'+secrets.token_hex(24)).encode())
        variants[variant]={'base':str(base),'sourceBase':str(profile_row['source']),
            'sourceConfigSha256':profile_row['configSha256'],'configSha256':hashlib.sha256(raw).hexdigest(),
            'binaries':{k:row[k] for k in ('server','daemon','fc')},
            'apiPort':18130 if variant=='original' else 18131,
            'unit':'aenv-hpd4-'+node+'-'+variant+'.service',
            'proxyUnit':'aenv-hpd4-'+node+'-'+variant+'-proxy.service',
            'apiSocket':str(work/('api-'+variant+'.sock')),'fcWorkDir':str(work/(variant+'-fc')),
            'snapshotStore':str(snapshot_store),'snapshotReadOnlyBindRequired':True,
            'hostDaxRootfsIndex':None if variant=='original' else '/var/lib/agentenv-hpd4/public/node-'+node+'-runtime-index.json'}
    report.update(status='HOST_DAX_RUNTIME_FILES_STAGED_NOT_STARTED',variants=variants,
        guestReadProbe={'path':str(stage/'guest-read-probe-aarch64'),'sha256':PROBE_SHA,'staticAarch64':True,
                        'hostSelfTestPassed':True,'guestExecuted':False},
        hostNamespaces={'net':os.stat('/proc/self/ns/net').st_ino,'mnt':os.stat('/proc/self/ns/mnt').st_ino},
        bootId=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
        originalObserverIsDiagnosticBuild=True,UBOnlyCausalAttribution=False,
        versionDifference='Original diagnostic daemon and full candidate/FC builds differ; performance is whole-version comparison')
    put(stage/'staged.json',(json.dumps(report,indent=2)+'\n').encode())
    print('BEGIN_HOST_DAX_RUNTIME_STAGE');print(json.dumps(report,indent=2));print('END_HOST_DAX_RUNTIME_STAGE')

if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'status':'HOST_DAX_RUNTIME_STAGE_STOPPED_PRESERVE_FILES','reason':str(error),
                          'servicesChanged':False,'SDK_called':False,'Guest_created':False,'moduleChanged':False}));raise SystemExit(1)
